    '--   :P402_PRATR_ID_CURR := null;',
    '--   :P402_PRATR_ID := null;',
    '--   :P402_PRD_ID_CURR := null;',
    '--   :P402_PRD_ID := null;  ',
    '      if :P402_PR_ID_CURR is null then',
    '          begin',
    '            select PR_ID into :P402_PR_ID_CURR from REHAB_PRESCRIPTIONS where PR_PRR_ID = :P402_PRR_ID_CURR and rownum = 1;',
