    '      :P402_PR_ID := :P402_PR_ID_CURR;',
    '      :P402_PRATR_ID := :P402_PRATR_ID_CURR;',
    '      :P402_PRD_ID := :P402_PRD_ID_CURR;',
    'end;')),
  'show_processing', 'N',
  'suppress_change_event', 'N')).to_clob
