,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_submit', 'P402_PRR_ID,P402_PR_ID,P402_PR_DR_ID,P402_PR_WS_ID,P402_PR_NOTES,P402_PR_PLANNED_START,P402_PR_PLANNED_END',
